import java.util.Arrays;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class JSONParserHelper {

    private Class<?> clazz;
    private FieldDeserializer[] sortedFieldDeserializers;
    private long[] smartMatchHashArray;
    private int[] smartMatchHashArrayMapping;
    private Map<String, Object> extraFieldDeserializers;
    private BeanInfo beanInfo;

    private FieldDeserializer getFieldDeserializer(String key) {
